//! Camel-case IPC and persisted profile contracts shared with the TypeScript UI.
//!
//! The bundled JSON catalog is the common default source for Rust and the browser.
//! Counters use floating-point numbers to preserve existing fractional game metrics;
//! validation rejects negative, nonfinite, and JavaScript-unsafe values.

use serde::{Deserialize, Serialize};
use serde_json::Value;

/// Largest exact integer supported by JavaScript number values.
pub const MAX_SAFE_NUMBER: f64 = 9_007_199_254_740_991.0;

/// Completed-run input; identity and completion timestamp are generated by Rust.
#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct RunInput {
    /// Final score before recording progression.
    pub score: f64,
    /// Completed distance in game meters.
    pub distance_meters: f64,
    /// Coin pickups, not multiplied score.
    pub coins_collected: f64,
    /// Relic pickups.
    pub relics_collected: f64,
    /// Scene-reported avoidance events.
    pub hazards_avoided: f64,
    /// Manual vine releases.
    pub vines_swung: f64,
    /// Scene cause code retained verbatim for compatibility.
    pub cause_of_death: String,
    /// Explorer ID for the expedition.
    pub character_id: String,
    /// Requested generation seed; negative integer seeds remain supported.
    pub seed: i64,
    /// Expedition life/fall rules.
    pub mode: GameMode,
}

/// Serializable rule identities matching the frontend union.
#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(rename_all = "lowercase")]
pub enum GameMode {
    /// Three-life expedition.
    Endless,
    /// Practice recovery rules.
    Practice,
    /// User-seeded expedition.
    Challenge,
}

/// Persisted run retaining the original flat JSON shape.
#[derive(Clone, Debug, Deserialize, Serialize)]
pub struct RunRecord {
    /// Unique completion ID generated from time plus a process-local sequence.
    pub id: String,
    /// Epoch milliseconds of completion.
    pub timestamp: u64,
    /// Gameplay metrics flattened into the surrounding record.
    #[serde(flatten)]
    pub input: RunInput,
}

/// Lifetime totals and single-run bests.
#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct PlayerStats {
    /// Completed expeditions.
    pub total_runs: f64,
    /// Sum of completed-run game meters.
    pub total_distance_meters: f64,
    /// Lifetime coin pickups.
    pub total_coins: f64,
    /// Lifetime relic pickups.
    pub total_relics: f64,
    /// Greatest completed score.
    pub high_score: f64,
    /// Greatest completed distance.
    pub longest_distance_meters: f64,
    /// Greatest single-run vine-release count.
    pub most_vines_swung_in_single_run: f64,
    /// Sum of reported avoidance events.
    pub total_hazards_avoided: f64,
    /// Most recent completion in epoch milliseconds.
    pub last_played_timestamp: u64,
}

/// Physical keyboard code aliases for logical game actions.
#[derive(Clone, Debug, Deserialize, Serialize)]
pub struct KeyBindings {
    /// Jump/release aliases.
    pub jump: Vec<String>,
    /// Slide aliases.
    pub slide: Vec<String>,
    /// Vine attachment aliases.
    pub interact: Vec<String>,
    /// Pause toggle aliases.
    pub pause: Vec<String>,
}

/// Persisted audio, presentation, and input preferences.
#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct GameSettings {
    /// Normalized music volume in [0, 1].
    pub music_volume: f64,
    /// Normalized sound-effect volume in [0, 1].
    pub sfx_volume: f64,
    /// Master mute flag.
    pub is_muted: bool,
    /// Camera-impact preference.
    pub screen_shake: bool,
    /// Reserved particle-quality setting.
    pub particle_density: String,
    /// Auto/always/never virtual-control visibility.
    pub show_touch_controls: String,
    /// Complete physical-code mapping.
    pub key_bindings: KeyBindings,
}

/// Known achievement metadata and persisted completion state.
#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct Achievement {
    /// Stable progression-rule key.
    pub id: String,
    /// Display title used in unlock notifications.
    pub title: String,
    /// Player-facing goal description.
    pub description: String,
    /// Presentation category.
    pub category: String,
    /// Current goal-specific metric.
    pub progress: f64,
    /// Goal target.
    pub max_progress: f64,
    /// Whether completion has already been reported.
    pub unlocked: bool,
    /// Completion time, omitted until unlocking.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub unlocked_at: Option<u64>,
}

/// Character presentation metadata; sprite palettes remain owned by the boot scene.
#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct CharacterSkin {
    /// Stable explorer/texture key.
    pub id: String,
    /// Explorer display name.
    pub name: String,
    /// Role subtitle.
    pub title: String,
    /// Flavor description.
    pub description: String,
    /// Selectability flag.
    pub unlocked: bool,
    /// Display text for a locked explorer.
    pub unlock_requirement: String,
    /// Catalog CSS palette values.
    pub color_theme: ColorTheme,
}

/// Serializable character palette.
#[derive(Clone, Debug, Deserialize, Serialize)]
pub struct ColorTheme {
    /// Shirt CSS color.
    pub shirt: String,
    /// Trouser CSS color.
    pub pants: String,
    /// Hat CSS color.
    pub hat: String,
    /// Accent CSS color.
    pub accent: String,
}

/// Native-owned aggregate returned as a frontend snapshot after each successful mutation.
#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct LocalProfile {
    /// Current schema revision; unsupported future revisions are rejected.
    pub schema_version: u32,
    /// Successful mutation time in epoch milliseconds.
    pub last_updated: u64,
    /// Preferred known unlocked explorer.
    pub selected_character_id: String,
    /// Accumulated totals and bests.
    pub stats: PlayerStats,
    /// Persisted preferences.
    pub settings: GameSettings,
    /// All known goals, including locked ones.
    pub achievements: Vec<Achievement>,
    /// All known skins, despite the historical name.
    pub unlocked_skins: Vec<CharacterSkin>,
    /// Newest-first history, capped at 30 on recording and 50 on loading.
    pub recent_runs: Vec<RunRecord>,
}

/// Completion outcome with the same JSON shape as the browser repository.
#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct RecordOutcome {
    /// Successfully persisted aggregate.
    pub profile: LocalProfile,
    /// Strictly greater score, not a tie.
    pub new_high_score: bool,
    /// Strictly greater completed distance.
    pub new_longest_distance: bool,
    /// Newly unlocked display titles.
    pub unlocked_achievements: Vec<String>,
    /// Newly selectable explorer names.
    pub unlocked_skins: Vec<String>,
}

/// Validated native operation envelope accepted by the single IPC command.
#[derive(Debug, Deserialize)]
#[serde(
    tag = "operation",
    rename_all = "camelCase",
    rename_all_fields = "camelCase"
)]
pub enum DataRequest {
    /// Load existing native data; null indicates that browser migration is needed.
    LoadProfile,
    /// Create native data once, without replacing an existing native save.
    InitializeProfile {
        /// Legacy browser aggregate, or null for a new install.
        legacy_profile: Option<Value>,
    },
    /// Shallow preference patch; unknown fields are rejected by the repository.
    UpdateSettings {
        /// Preference keys/values supplied by the UI.
        settings: Value,
    },
    /// Select a known unlocked explorer.
    SelectCharacter {
        /// Stable explorer ID.
        character_id: String,
    },
    /// Accumulate one completed expedition.
    RecordRun {
        /// Metrics before repository-generated identity/time.
        run_data: RunInput,
    },
    /// Serialize the native aggregate off the WebView thread.
    ExportData,
    /// Normalize/validate a backup before committing it.
    ImportData {
        /// Pasted JSON backup, not a file path supplied by the WebView.
        json_string: String,
    },
    /// Persist a fresh default aggregate.
    ResetAllData,
}
